import React, { useState } from "react";
import SubNavbar from "../components/SubNavbar";
import { useCart } from "../context/CartContext";
import Navbar from "../components/Navbar";

export type Category = "Electronics" | "Fashion" | "Home" | "Books";

interface Product {
  name: string;
  price: number;
  image: string;
}

const Products: React.FC = () => {
  const categories: Category[] = ["Electronics", "Fashion", "Home", "Books"];
  const [selectedCategory, setSelectedCategory] = useState<Category>(categories[0]);
  const { addToCart } = useCart();
  const [searchTerm, setSearchTerm] = useState("");

  const [showSuccess, setShowSuccess] = useState(false);
  // To store the name of the item just added
  const [addedItem, setAddedItem] = useState<string>("");


  const allProducts: Record<Category, Product[]> = {
    Electronics: [
      { name: "Laptop", price: 999, image: "https://th.bing.com/th/id/OIP.u-WMhEdVK8Djt3-3mB5x_AHaF7?w=216&h=180&c=7&r=0&o=7&cb=12&dpr=1.3&pid=1.7&rm=3" },
      { name: "Smartphone", price: 799, image: "https://th.bing.com/th?id=OPHS.7C11fQ6xE%2f1n5Q474C474&o=5&pid=21.1&w=140&h=220&dpr=1.3&o=7&rm=3" },
      { name: "Headphones", price: 249, image: "https://m.media-amazon.com/images/I/61SNDXZcmTL._AC_UY327_FMwebp_QL65_.jpg" },
      { name: "Camera", price: 499, image: "data:image/webp;base64," },
    ],
    Fashion: [
      { name: "T-Shirt", price: 25, image: "https://th.bing.com/th/id/OIP.A9pMlYPGSn01AT2dRMa8jgHaIr?w=171&h=200&c=7&r=0&o=7&cb=12&dpr=1.3&pid=1.7&rm=3" },
      { name: "Jeans", price: 45, image: "https://th.bing.com/th/id/OIP.qmSPML52uPxr1pIIYFfx-AAAAA?w=208&h=297&c=7&r=0&o=7&cb=12&dpr=1.3&pid=1.7&rm=3" },
      { name: "Sneakers", price: 80, image: "https://th.bing.com/th/id/OIP.ihSWAynh05dQw2KVi2QalQHaHa?w=184&h=184&c=7&r=0&o=7&cb=12&dpr=1.3&pid=1.7&rm=3" },
      { name: "Jacket", price: 120, image: "data:image/webp;base64," },
    ],
    Home: [
      { name: "Sofa", price: 550, image: "https://th.bing.com/th/id/OIP.OUfLKAeiGxUfLE-BszuU0wHaE8?w=276&h=184&c=7&r=0&o=7&cb=12&dpr=1.3&pid=1.7&rm=3" },
      { name: "Lamp", price: 40, image: "data:image/webp;base64," },
      { name: "Dining Table", price: 300, image: "https://th.bing.com/th/id/OIP.FNgyKXL1dlle9ATuBXX-9QHaHa?w=187&h=187&c=7&r=0&o=7&cb=12&dpr=1.3&pid=1.7&rm=3" },
      { name: "Curtains", price: 60, image: "data:image/webp;base64," },
    ],
    Books: [
      { name: "Atomic Habits", price: 18, image: "https://th.bing.com/th/id/OIP.v1RBydM3JpB2kxM_KAZonwHaJl?w=137&h=180&c=7&r=0&o=7&cb=12&dpr=1.3&pid=1.7&rm=3" },
      { name: "The Great Gatsby", price: 15, image: "https://th.bing.com/th/id/OIP.MSu1wkGWxI_-D58jiDFjogHaJt?w=208&h=273&c=7&r=0&o=7&cb=12&dpr=1.3&pid=1.7&rm=3" },
      { name: "Rich Dad Poor Dad", price: 20, image: "data:image/webp;base64," },
      { name: "1984", price: 16, image: "https://th.bing.com/th/id/OIP.RU9EG7SwALpakSkWe4tcEgHaL2?w=197&h=316&c=7&r=0&o=7&cb=12&dpr=1.3&pid=1.7&rm=3" },
    ],
  };
  // Combine all category arrays into one flat array for global searching
  const allItems = Object.values(allProducts).flat();
  const filteredItems = searchTerm
    ? allItems.filter((product) =>
        product.name.toLowerCase().includes(searchTerm.toLowerCase())
      )
    : allProducts[selectedCategory];

  const handleCategoryChange = (category: Category) => {
    setSelectedCategory(category);
  };

  return (
    <div style={{ margin: 0, padding: 0 }}>
      {/* ✅ Navbar must be inside return */}
      <Navbar onSearchChange={setSearchTerm} />

      {/* SubNavbar */}
      <SubNavbar
        categories={categories}
        selectedCategory={selectedCategory}
        onCategoryChange={handleCategoryChange}
      />
      
      {/* Success alert */}
      {showSuccess && (
        <div
          style={{
            position: "fixed",
            bottom: "30px",
            left: "50%",
            transform: "translateX(-50%)",
            backgroundColor: "#28a745",
            color: "white",
            padding: "15px 30px",
            borderRadius: "10px",
            boxShadow: "0 2px 10px rgba(0,0,0,0.3)",
          }}
        >
         {addedItem} added to cart successfully!
        </div>
      )}

      {/* Product Grid */}
      <div style={{ marginTop: "20px", textAlign: "center" }}>
        {/* ✅ Dynamic title */}
        <h2>
          {searchTerm.trim() ? "Search Results" : selectedCategory}
        </h2>
        <div
          style={{
            display: "flex",
            justifyContent: "center",
            gap: "20px",
            flexWrap: "wrap",
            marginTop: "20px",
          }}
        >
          {(searchTerm
              ? allItems.filter((product) =>
                  product.name.toLowerCase().includes(searchTerm.toLowerCase())
                ) //  show all matches across categories
              : allProducts[selectedCategory] //  default to selected category
            ).map((product) => (

            <div
              key={product.name}
              style={{
                width: "280px",
                padding: "15px",
                border: "1px solid #ddd",
                borderRadius: "8px",
                backgroundColor: "#fff",
                boxShadow: "0 2px 5px rgba(0,0,0,0.1)",
              }}
            >
              <img
                src={product.image}
                alt={product.name}
                style={{
                  width: "100%",
                  height: "200px",
                  objectFit: "contain",
                  borderRadius: "10px"
                }}
              />
              <h4 style={{ margin: "8px 0" }}>{product.name}</h4>
              <p style={{ fontSize: "14px", color: "#333", marginBottom: "10px" }}>
                ${product.price.toFixed(2)}
              </p>
              <button
                onClick={() => {
                  addToCart({
                    name: product.name,
                    price: product.price,
                    image: product.image,
                  });
                  setAddedItem(product.name); // store the name of the added item
                  setShowSuccess(true); // show success alert
                  setTimeout(() => setShowSuccess(false), 2000); // hide after 2s
                }}
                style={{
                  backgroundColor: "#edca03",
                  color: "black",
                  fontWeight: "bold",
                  border: "1px solid black",
                  borderRadius: "5px",
                  padding: "6px 12px",
                  cursor: "pointer",
                  transition: "0.2s",
                }}
                onMouseEnter={(e) => (e.currentTarget.style.backgroundColor = "#ffd700")}
                onMouseLeave={(e) => (e.currentTarget.style.backgroundColor = "#edca03")}
              >
                Add to Cart
              </button>
            </div>
          ))}
          {/* Show message when no results */}
          {searchTerm &&
          allItems.filter((product) =>
            product.name.toLowerCase().includes(searchTerm.toLowerCase())
          ).length === 0 && (
            <p style={{ marginTop: "20px", fontStyle: "italic" }}>
              No products found.
            </p>
          )}
        </div>
      </div>
    </div>
  );
};

export default Products;
